function _verifyTokensSupplied() internal view virtual {
    if (!s_saleStatus.tokensSupplied) revert Errors.LegionSale__TokensNotSupplied();
}

/// @dev Verifies that an investment signature is valid.
/// @param _signature The signature to verify.
function _verifyInvestSignature(bytes calldata _signature) internal view virtual {
    bytes32 _data = keccak256(abi.encodePacked(msg.sender, address(this), block.chainid)).toEthSignedMessageHash();

    if (_data.recover(_signature) != s_addressConfig.legionSigner) {
        revert Errors.LegionSale__InvalidSignature(_signature);
    }
}

/// @dev Verifies conditions for withdrawing capital.
function _verifyCanWithdrawCapital() internal view virtual {
    // Load the sale status
    LegionSaleStatus memory _saleStatus = s_saleStatus;

    if (_saleStatus.capitalWithdrawn) revert Errors.LegionSale__CapitalAlreadyWithdrawn();
    if (_saleStatus.totalCapitalRaised == 0) revert Errors.LegionSale__CapitalNotRaised();
}

/// @dev Verifies that the investor has not refunded.
/// @param _positionId The ID of the investor's position.
function _verifyHasNotRefunded(uint256 _positionId) internal view virtual {
    if (s_investorPositions[_positionId].hasRefunded) revert Errors.LegionSale__InvestorHasRefunded(msg.sender);
}

/// @dev Verifies that the investor has not claimed excess capital.

    s_fixedPriceSaleConfig.prefundStartTime = uint64(block.timestamp);
    s_fixedPriceSaleConfig.prefundEndTime =
        s_fixedPriceSaleConfig.prefundStartTime + fixedPriceSaleInitParams.prefundPeriodSeconds;

    // Calculate and set startTime, endTime and refundEndTime
    s_saleConfig.startTime =
        s_fixedPriceSaleConfig.prefundEndTime + fixedPriceSaleInitParams.prefundAllocationPeriodSeconds;
    s_saleConfig.endTime = s_saleConfig.startTime + saleInitParams.salePeriodSeconds;
    s_saleConfig.refundEndTime = s_saleConfig.endTime + saleInitParams.refundPeriodSeconds;
}

/// @inheritdoc ILegionFixedPriceSale
function invest(
    uint256 amount,
    bytes calldata signature
)
    external
    whenNotPaused
    whenNotPrefundAllocationPeriod
    whenSaleNotEnded
    whenSaleNotCanceled
{
    // Check if the investor has already invested
    // If not, create a new investor position
    uint256 positionId = _getInvestorPositionId(msg.sender) == 0
        ? _createInvestorPosition(msg.sender)
        : s_investorPositionIds[msg.sender];

    // Verify that the investor is allowed to invest capital
    _verifyInvestSignature(signature);

    // Verify that the amount invested is more than the minimum required
    _verifyMinimumInvestAmount(amount);

    // Verify that the investor has not refunded
    _verifyHasNotRefunded(positionId);

    // Verify that the investor has not claimed excess capital
    _verifyHasNotClaimedExcess(positionId);

    // Increment total capital invested from investors
    s_saleStatus.totalCapitalInvested += amount;

    // Increment total invested capital for the investor
    s_investorPositions[positionId].investedCapital += amount;

    // Flag if capital is invested during the prefund period
    bool isPrefund = _isPrefund();

    // Emit CapitalInvested event
    emit CapitalInvested(amount, msg.sender, isPrefund, positionId);

    // Transfer the invested capital to the contract
    SafeTransferLib.safeTransferFrom(s_addressConfig.bidToken, msg.sender, address(this), amount);
}

/// @inheritdoc ILegionFixedPriceSale
function publishSaleResults(
    bytes32 claimMerkleRoot,
    bytes32 acceptedMerkleRoot,
    uint256 tokensAllocated,
    uint8 askTokenDecimals
)
    external
    onlyLegion
    whenNotPaused
    whenSaleNotCanceled
    whenRefundPeriodIsOver
{
    // Verify that sale results are not already published

}

/// @inheritdoc ILegionPreLiquidOpenApplicationSale
function invest(
    uint256 amount,
    bytes calldata signature
)
    external
    whenNotPaused
    whenSaleNotEnded
    whenSaleNotCanceled
{
    // Check if the investor has already invested
    // If not, create a new investor position
    uint256 positionId = _getInvestorPositionId(msg.sender) == 0
        ? _createInvestorPosition(msg.sender)
        : s_investorPositionIds[msg.sender];

    // Verify that the investor is allowed to invest capital
    _verifyInvestSignature(signature);

    // Verify that the amount invested is more than the minimum required
    _verifyMinimumInvestAmount(amount);

    // Verify that the investor has not refunded
    _verifyHasNotRefunded(positionId);

    // Verify that the investor has not claimed excess capital
    _verifyHasNotClaimedExcess(positionId);

    // Increment total capital invested from all investors
    s_saleStatus.totalCapitalInvested += amount;

    // Increment total invested capital for the investor
    s_investorPositions[positionId].investedCapital += amount;

    // Emit CapitalInvested event
    emit CapitalInvested(amount, msg.sender, positionId);

    // Transfer the invested capital to the contract
    SafeTransferLib.safeTransferFrom(s_addressConfig.bidToken, msg.sender, address(this), amount);
}

/// @inheritdoc ILegionPreLiquidOpenApplicationSale
function end() external onlyLegionOrProject whenNotPaused whenSaleNotCanceled whenSaleNotEnded {
    // Update the `hasEnded` status to true
    s_preLiquidSaleConfig.hasEnded = true;

    // Set the `endTime` of the sale
    s_saleConfig.endTime = uint64(block.timestamp);

    // Set the `refundEndTime` of the sale
    s_saleConfig.refundEndTime = uint64(block.timestamp) + s_preLiquidSaleConfig.refundPeriodSeconds;

    // Emit SaleEnded event
    emit SaleEnded();
}

/// @inheritdoc ILegionPreLiquidOpenApplicationSale
function publishRaisedCapital(uint256 capitalRaised)

/// @inheritdoc ILegionSealedBidAuctionSale
function invest(
    uint256 amount,
    bytes calldata sealedBid,
    bytes calldata signature
)
    external
    whenNotPaused
    whenSaleNotEnded
    whenSaleNotCanceled
{
    // Check if the investor has already invested
    // If not, create a new investor position
    uint256 positionId = _getInvestorPositionId(msg.sender) == 0
        ? _createInvestorPosition(msg.sender)
        : s_investorPositionIds[msg.sender];

    // Verify that the investor is allowed to invest capital
    _verifyInvestSignature(signature);

    // Decode the sealed bid data
    (uint256 encryptedAmountOut, Point memory sealedBidPublicKey) = abi.decode(sealedBid, (uint256, Point));

    // Verify that the provided public key is valid
    _verifyValidPublicKey(sealedBidPublicKey);

    // Verify that the amount invested is more than the minimum required
    _verifyMinimumInvestAmount(amount);

    // Verify that the investor has not refunded
    _verifyHasNotRefunded(positionId);

    // Verify that the investor has not claimed excess capital
    _verifyHasNotClaimedExcess(positionId);

    // Increment total capital invested from all investors
    s_saleStatus.totalCapitalInvested += amount;

    // Increment total invested capital for the investor
    s_investorPositions[positionId].investedCapital += amount;

    // Emit CapitalInvested event
    emit CapitalInvested(amount, encryptedAmountOut, msg.sender, positionId);

    // Transfer the invested capital to the contract
    SafeTransferLib.safeTransferFrom(s_addressConfig.bidToken, msg.sender, address(this), amount);
}

/// @inheritdoc ILegionSealedBidAuctionSale
function initializePublishSaleResults()
    external
    onlyLegion
    whenNotPaused
    whenSaleNotCanceled
    whenCancelNotLocked
    whenRefundPeriodIsOver
{
    // Verify that sale results are not already published
    _verifyCanPublishSaleResults();

/// @inheritdoc ILegionPreLiquidApprovedSale
function invest(
    uint256 amount,
    uint256 investAmount,
    uint256 tokenAllocationRate,
    bytes calldata investSignature
)
    external
    whenNotPaused
    whenSaleNotCanceled
    whenSaleNotEnded
{
    // Check if the investor has already invested
    // If not, create a new investor position
    uint256 positionId = _getInvestorPositionId(msg.sender) == 0
        ? _createInvestorPosition(msg.sender)
        : s_investorPositionIds[msg.sender];

    // Verify that the investor has not refunded
    _verifyHasNotRefunded(positionId);

    // Verify that the signature has not been used
    _verifySignatureNotUsed(investSignature);

    // Verify that the investor has not claimed excess capital
    _verifyCanClaimExcessCapital(positionId);

    // Load the investor position
    InvestorPosition storage position = s_investorPositions[positionId];

    // Increment total capital invested from investors
    s_saleStatus.totalCapitalInvested += amount;

    // Increment total capital for the investor
    position.investedCapital += amount;

    // Mark the signature as used
    s_usedSignatures[msg.sender][investSignature] = true;

    // Update the investor position
    _updateInvestorPosition(investAmount, tokenAllocationRate, positionId);

    // Verify that the investor position is valid
    _verifyValidPosition(investSignature, positionId, SaleAction.INVEST);

    // Emit CapitalInvested event
    emit CapitalInvested(amount, msg.sender, positionId);

    // Transfer the invested capital to the contract
    SafeTransferLib.safeTransferFrom(s_saleConfig.bidToken, msg.sender, address(this), amount);
}

/// @inheritdoc ILegionPreLiquidApprovedSale
function refund() external whenNotPaused whenSaleNotCanceled whenRefundPeriodNotOver {
    // Get the investor position ID
    uint256 positionId = _getInvestorPositionId(msg.sender);

    // Verify that the position exists
    _verifyPositionExists(positionId);

    // Verify that the investor has not refunded
    _verifyHasNotRefunded(positionId);

    // Load the investor position
    InvestorPosition storage position = s_investorPositions[positionId];

    // Cache the amount to refund
    uint256 amountToRefund = position.investedCapital;

